CREATE TABLE `integration_requests` (`id` text PRIMARY KEY NOT NULL, `user_id` text, `api_key_id` text, `audience` text NOT NULL, `request_type` text NOT NULL, `status` text NOT NULL, `holder_did` text, `created_at` text NOT NULL, FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade, FOREIGN KEY (`api_key_id`) REFERENCES `api_keys`(`id`) ON UPDATE no action ON DELETE set null);